draw:
function arrow(x1,y1,x2,y2,col,wid){
  ctx.strokeStyle=col; ctx.fillStyle=col; ctx.lineWidth=wid;
  ctx.beginPath(); ctx.moveTo(x1,y1); ctx.lineTo(x2,y2); ctx.stroke();
  var a=Math.atan2(y2-y1,x2-x1), s=7;
  ctx.beginPath();
  ctx.moveTo(x2,y2);
  ctx.lineTo(x2-s*Math.cos(a-0.4), y2-s*Math.sin(a-0.4));
  ctx.lineTo(x2-s*Math.cos(a+0.4), y2-s*Math.sin(a+0.4));
  ctx.closePath(); ctx.fill();
}

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
var n = Math.round(p.sides);
var I = p.current, a = p.side / 100;
var mu = 4 * Math.PI * 1e-7;
var d = a / (2 * Math.tan(Math.PI / n));
var Bside = mu * I / (4 * Math.PI * d) * 2 * Math.sin(Math.PI / n);
var B = n * Bside;
var Rcirc = a / (2 * Math.sin(Math.PI / n));
var Bcirc = mu * I / (2 * Rcirc);

var cx = W * 0.32, cy = H * 0.52;
var rad = Math.min(W * 0.24, H * 0.36);
ctx.strokeStyle = C.accent; ctx.lineWidth = 2.5;
ctx.beginPath();
for (var i = 0; i <= n; i++) {
  var ang = -Math.PI / 2 + 2 * Math.PI * i / n;
  var x = cx + rad * Math.cos(ang), y = cy + rad * Math.sin(ang);
  if (i === 0) { ctx.moveTo(x, y); } else { ctx.lineTo(x, y); }
}
ctx.stroke();

// the circle the corners sit on
ctx.strokeStyle = C.faint; ctx.lineWidth = 1; ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.arc(cx, cy, rad, 0, Math.PI * 2); ctx.stroke();
ctx.setLineDash([]);

// perpendicular from centre to one side
var a0 = -Math.PI / 2 + Math.PI / n;
var mx = cx + rad * Math.cos(a0) * Math.cos(Math.PI / n);
var my = cy + rad * Math.sin(a0) * Math.cos(Math.PI / n);
ctx.strokeStyle = C.figure; ctx.lineWidth = 1.5;
ctx.beginPath(); ctx.moveTo(cx, cy); ctx.lineTo(mx, my); ctx.stroke();
ctx.fillStyle = C.figure;
ctx.fillText("d", (cx + mx) / 2 + 6, (cy + my) / 2);

ctx.fillStyle = C.ink;
ctx.beginPath(); ctx.arc(cx, cy, 3, 0, Math.PI * 2); ctx.fill();
ctx.fillText("centre", cx - 18, cy + 18);
ctx.fillStyle = C.accent;
ctx.fillText(n + " sides, " + (a * 100).toFixed(0) + " cm each", cx - rad, cy - rad - 12);

// bar chart: one side, whole polygon, the circle of the same corner radius
var bx = W * 0.62, by = H * 0.22, bw = W * 0.30, rowh = 22;
var top = Math.max(B, Bcirc);
function row(lab, val, k, col) {
  ctx.fillStyle = C.ink;
  ctx.fillText(lab, bx, by + k * (rowh + 16) - 4);
  ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
  ctx.strokeRect(bx, by + k * (rowh + 16), bw, 12);
  ctx.fillStyle = col;
  ctx.fillRect(bx, by + k * (rowh + 16), bw * (val / top), 12);
  ctx.fillStyle = C.ink;
  ctx.fillText((val * 1e6).toFixed(1) + " uT", bx, by + k * (rowh + 16) + 24);
}
row("one side alone", Bside, 0, C.figure);
row("all " + n + " sides", B, 1, C.accent);
row("circle through the corners", Bcirc, 2, C.rule);

out.note = "polygon centre B = " + (B * 1e6).toFixed(2) + " microtesla; the circle through its corners gives " + (Bcirc * 1e6).toFixed(2) + " microtesla. Raise the number of sides and the two close in on each other.";
